def is_balanced(s):
    """Return whether the ASCII brackets in s are correctly nested."""
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    stack = []
    for char in s:
        if char in OPEN:
            stack.append(char)
        elif char in CLOSE:
            if not stack or stack.pop() != PAIRS[char]:
                return False
    return not stack

